package com.flightparty.table;
import java.util.*;
/** Casual shared-target pool. Physics and pockets are simulated on the server.
 * Command = spot * 363600 + power * 3600 + angle. Spot 0 preserves legacy center hits;
 * 1..8 run clockwise from top: follow, follow-right, right, draw-right, draw, draw-left,
 * left, follow-left. Spin is a bounded arcade approximation, not a rigid-body model. */
public final class PoolRules {
 private static final int PENALTY_VISIT=52, PENALTY_READY=1, PENALTY_ACTIVE=2;
 public static GridRules.State start(){int[] c=new int[PENALTY_VISIT+1];c[0]=2500;c[1]=2500;c[2]=1;int[] rack={1,9,2,10,8,3,4,11,5,12,6,13,7,14,15};int k=0;for(int col=0;col<5;col++)for(int row=0;row<=col;row++){int n=rack[k++];c[n*3]=6500+col*282;c[n*3+1]=2500+(int)Math.round((row-col*.5)*326);c[n*3+2]=1;}return new GridRules.State("pool",c,1,0,false,0,"",List.of());}
 // 2ms quarter-steps retain original per-second damping; history remains sampled every 16ms.
 public static GridRules.State move(GridRules.State s,int actor,int command){if(s.over()||actor!=s.turn())throw new IllegalStateException();int spinCode=command/363600,shot=command%363600,power=shot/3600,angle=shot%3600;if(command<0||spinCode>8||power<1||power>100)throw new IllegalArgumentException();double q=Math.sqrt(.5),side=new double[]{0,0,q,1,q,0,-q,-1,-q}[spinCode],follow=new double[]{0,1,q,0,-q,-1,-q,0,q}[spinCode],spinLife=1;boolean contactSpin=false;double[] x=new double[16],y=new double[16],vx=new double[16],vy=new double[16];boolean[] alive=new boolean[16];int[] c=Arrays.copyOf(s.cells(),PENALTY_VISIT+1);for(int i=0;i<16;i++){x[i]=c[i*3]/10.;y[i]=c[i*3+1]/10.;alive[i]=c[i*3+2]==1;}vx[0]=Math.cos(angle*Math.PI/1800)*power*.48;vy[0]=Math.sin(angle*Math.PI/1800)*power*.48;var frames=new ArrayList<String>();int pocket=0,firstContact=0;var potted=new ArrayList<Integer>();boolean scratch=false,black=false;
 for(int step=0;step<4800;step++){double speed=0;for(int i=0;i<16;i++)if(alive[i]){x[i]+=vx[i]*.25;y[i]+=vy[i]*.25;if(PoolGeometry.pocketIndex(x[i],y[i])>=0){alive[i]=false;potted.add(i);vx[i]=vy[i]=0;if(i==0)scratch=true;else if(i==8)black=true;else pocket++;continue;}var rail=PoolGeometry.resolveCushion(x[i],y[i],vx[i],vy[i]);x[i]=rail.x();y[i]=rail.y();vx[i]=rail.vx();vy[i]=rail.vy();if(rail.hit()&&i==0&&side!=0){double magnitude=Math.hypot(vx[i],vy[i]);vx[i]-=rail.ny()*rail.normalSpeed()*side*.32*spinLife;vy[i]+=rail.nx()*rail.normalSpeed()*side*.32*spinLife;double scale=magnitude/Math.hypot(vx[i],vy[i]);vx[i]*=scale;vy[i]*=scale;}vx[i]*=Math.pow(.991,.25);vy[i]*=Math.pow(.991,.25);if(Math.hypot(vx[i],vy[i])<.035)vx[i]=vy[i]=0;speed+=Math.hypot(vx[i],vy[i]);}
 for(int i=0;i<16;i++)for(int j=i+1;j<16;j++)if(alive[i]&&alive[j]){double dx=x[j]-x[i],dy=y[j]-y[i],d=Math.hypot(dx,dy);if(d>0&&d<32){double nx=dx/d,ny=dy/d,overlap=(32-d)/2;x[i]-=nx*overlap;y[i]-=ny*overlap;x[j]+=nx*overlap;y[j]+=ny*overlap;double impulse=(vx[i]-vx[j])*nx+(vy[i]-vy[j])*ny;if(impulse>0){if(i==0&&firstContact==0)firstContact=j;double incomingX=vx[i],incomingY=vy[i],incomingSpeed=Math.hypot(incomingX,incomingY);vx[i]-=impulse*nx;vy[i]-=impulse*ny;vx[j]+=impulse*nx;vy[j]+=impulse*ny;if(i==0&&!contactSpin&&spinCode!=0){
 // Convert a finite spin budget once, scaled by the actual incoming speed and contact thickness.
 // Use the incoming direction after any cushion rebound; never accelerate beyond that speed.
 if(incomingSpeed>1e-9){double spinSpeed=Math.min(power*.48*spinLife,incomingSpeed)*Math.min(1,impulse/incomingSpeed),forward=spinSpeed*.36*follow,lateral=spinSpeed*.18*side,limit=Math.min(incomingSpeed,Math.sqrt(vx[0]*vx[0]+vy[0]*vy[0]+forward*forward+lateral*lateral));vx[0]+=(incomingX*forward-incomingY*lateral)/incomingSpeed;vy[0]+=(incomingY*forward+incomingX*lateral)/incomingSpeed;double outgoing=Math.hypot(vx[0],vy[0]);if(outgoing>limit){vx[0]*=limit/outgoing;vy[0]*=limit/outgoing;}}contactSpin=true;}}}}
 spinLife*=Math.pow(.997,.25);if(step%8==0&&frames.size()<600)frames.add(frame(x,y,alive));if(speed<.04&&step>1)break;}
 // Preserve a death frame when scratch occurs between 16ms replay samples.
 if(scratch){if(frames.isEmpty()||!frames.get(frames.size()-1).split(",")[2].equals("0"))frames.add(frame(x,y,alive));alive[0]=true;outer:for(int xx=180;xx<=420;xx+=30)for(int yy=80;yy<450;yy+=30){boolean free=true;for(int i=1;i<16;i++)if(alive[i]&&Math.hypot(xx-x[i],yy-y[i])<33)free=false;if(free){x[0]=xx;y[0]=yy;break outer;}}}
 for(int i=0;i<16;i++){c[i*3]=(int)Math.round(x[i]*10);c[i*3+1]=(int)Math.round(y[i]*10);c[i*3+2]=alive[i]?1:0;}var legal=targets(s.cells(),actor);boolean foul=scratch||!legal.contains(firstContact);if(!foul&&c[49+actor]==0){for(int id:potted)if(group(id)!=0){c[49+actor]=group(id);c[52-actor]=3-group(id);break;}}for(int seat=1;seat<=2;seat++){c[47+seat]=0;if(c[49+seat]!=0)for(int id=1;id<16;id++)if(group(id)==c[49+seat]&&c[id*3+2]==0)c[47+seat]++;}boolean own=false;for(int id:potted)if(group(id)!=0&&group(id)==c[49+actor])own=true;boolean over=black||s.moves()+1>=200;int winner=black?(!foul&&legal.size()==1&&legal.get(0)==8?actor:3-actor):over?(c[48]==c[49]?0:c[48]>c[49]?1:2):0;int penalty=c[PENALTY_VISIT];
 boolean useExtra=!foul&&!own&&penalty==PENALTY_READY;
 c[PENALTY_VISIT]=over?0:foul?PENALTY_READY:useExtra?PENALTY_ACTIVE:own&&penalty==PENALTY_READY?PENALTY_READY:0;
 String foulReason=scratch?"白球落袋":firstContact==0?"白球未碰到目标球":"白球先碰到非目标球";
 frames.add(frame(x,y,alive));
 return new GridRules.State("pool",c,!foul&&(own||useExtra)?actor:3-actor,winner,over,s.moves()+1,foul?"犯规："+foulReason:black?"8号球落袋":"本杆落袋 "+pocket+" 颗",frames,command);}
 private static String frame(double[] x,double[]y,boolean[]alive){var p=new ArrayList<String>();for(int i=0;i<16;i++){p.add(""+Math.round(x[i]*10));p.add(""+Math.round(y[i]*10));p.add(alive[i]?"1":"0");}return String.join(",",p);}
 public static int bot(GridRules.State s){int[] c=s.cells();int target=8;double best=Double.MAX_VALUE;for(int i:targets(c,s.turn())){double distance=Math.hypot(c[i*3]-c[0],c[i*3+1]-c[1]);if(distance<best){target=i;best=distance;}}double angle=Math.atan2(c[target*3+1]-c[1],c[target*3]-c[0]);int a=((int)Math.round(angle*1800/Math.PI)+3600)%3600;return 75*3600+a;}
 private static int group(int id){return id>0&&id<8?1:id>8&&id<16?2:0;}
 private static List<Integer> targets(int[] c,int actor){int g=c[49+actor];var ids=new ArrayList<Integer>();for(int id=1;id<16;id++)if(id!=8&&c[id*3+2]==1&&(g==0||group(id)==g))ids.add(id);if(ids.isEmpty()&&g!=0&&c[26]==1)ids.add(8);return ids;}}
